package com.lamsathob.studio;

import android.app.Activity;
import android.os.Bundle;
import android.os.Environment;
import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import java.io.File;
import java.io.FileOutputStream;
import java.util.Locale;

public class MainActivity extends Activity {
    private final int BG=Color.rgb(247,243,236), BLACK=Color.rgb(22,22,23), WOOD=Color.rgb(190,139,82), WHITE=Color.WHITE;
    private LinearLayout root; private ImageView preview; private Uri imageUri; private String material="خشب طبيعي";
    private android.content.SharedPreferences prefs;

    @Override public void onCreate(Bundle b){ super.onCreate(b); prefs=getSharedPreferences("lh",MODE_PRIVATE); home(); }

    private int dp(float n){ return (int)(n*getResources().getDisplayMetrics().density+.5f); }
    private GradientDrawable bg(int c,int r){ GradientDrawable g=new GradientDrawable(); g.setColor(c); g.setCornerRadius(dp(r)); return g; }
    private TextView text(String s,int size,boolean bold){ TextView v=new TextView(this); v.setText(s); v.setTextSize(size); v.setTextColor(BLACK); v.setGravity(Gravity.RIGHT); v.setPadding(dp(12),dp(9),dp(12),dp(9)); if(bold)v.setTypeface(android.graphics.Typeface.DEFAULT_BOLD); return v; }
    private Button button(String s,boolean wood){ Button b=new Button(this); b.setText(s); b.setTextSize(16); b.setAllCaps(false); b.setTextColor(wood?BLACK:WHITE); b.setBackground(bg(wood?WOOD:BLACK,16)); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(58)); p.setMargins(dp(5),dp(5),dp(5),dp(5)); b.setLayoutParams(p); return b; }
    private EditText input(String hint){ EditText e=new EditText(this); e.setHint(hint); e.setTextSize(16); e.setPadding(dp(14),0,dp(14),0); e.setBackground(bg(WHITE,14)); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(56)); p.setMargins(dp(5),dp(5),dp(5),dp(5)); e.setLayoutParams(p); return e; }
    private Spinner spinner(String[] a){ Spinner s=new Spinner(this); s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a)); s.setBackground(bg(WHITE,14)); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(58)); p.setMargins(dp(5),dp(5),dp(5),dp(5)); s.setLayoutParams(p); return s; }
    private void page(String title,String sub){ ScrollView sv=new ScrollView(this); sv.setBackgroundColor(BG); root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); root.setPadding(dp(12),dp(16),dp(12),dp(32)); sv.addView(root); if(!title.equals("Lamsat Hob Studio")){ Button back=button("← رجوع",false); back.setOnClickListener(v->home()); root.addView(back); } root.addView(text(title,28,true)); root.addView(text(sub,14,false)); setContentView(sv); }
    private void card(String title,String body){ LinearLayout c=new LinearLayout(this); c.setOrientation(LinearLayout.VERTICAL); c.setPadding(dp(16),dp(14),dp(16),dp(14)); c.setBackground(bg(BLACK,18)); TextView a=text(title,19,true); a.setTextColor(Color.rgb(238,199,130)); TextView b=text(body,14,false); b.setTextColor(Color.LTGRAY); c.addView(a); c.addView(b); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2); p.setMargins(dp(5),dp(7),dp(5),dp(7)); c.setLayoutParams(p); root.addView(c); }

    private void home(){ page("Lamsat Hob Studio","Design • Production • Gifts — كل أفكار لمسة حب قدامك"); card("لمسة حب","اختار القسم، شوف الخيارات، احفظ الطلب، وصدّر ملفات SVG الجاهزة للقوالب الهندسية."); String[] n={"➕ شغل جديد","🖼 Studio الصور","🪟 البرواز والعرض","🎁 التغليف","🎀 بوكسات الهدايا","🎉 المناسبات","💳 كارت المشروع","📋 الطلبات","📁 الملفات النهائية"}; for(int i=0;i<n.length;i++){ final int k=i; Button b=button(n[i],i==0); b.setOnClickListener(v->{ if(k==0)newJob(); else if(k==1)photos(); else if(k==2)frames(); else if(k==3)packaging(); else if(k==4)gifts(); else if(k==5)occasions(); else if(k==6)cards(); else if(k==7)orders(); else files(); }); root.addView(b); } }
    private void newJob(){ page("شغل جديد","اختار نوع الشغل بدل ما تعتمد عالذاكرة"); Button a=button("🖼 صورة / بورتريه",true); a.setOnClickListener(v->photos()); root.addView(a); Button b=button("🪟 برواز / عرض",false); b.setOnClickListener(v->frames()); root.addView(b); Button c=button("🎁 تغليف",false); c.setOnClickListener(v->packaging()); root.addView(c); Button d=button("🎀 بوكس هدية",false); d.setOnClickListener(v->gifts()); root.addView(d); }

    private void photos(){ page("Studio الصور","الخامة → الصورة → المقاس → الشكل → العرض"); card("مهم","Preview الأكريليك الأسود يساعدك تختار الاتجاه، لكن صورة الشخص النهائية للقص لازم تكون Stencil متصل مع Bridges قبل اعتبارها FINAL."); String[] mats={"خشب طبيعي","خشب أسود","أكريليك أسود","ستانلس"}; for(String m:mats){ Button b=button(m,false); b.setOnClickListener(v->{material=((Button)v).getText().toString(); Toast.makeText(this,"الخامة: "+material,Toast.LENGTH_SHORT).show(); render();}); root.addView(b); } Button pick=button("📷 اختار صورة من الهاتف",true); pick.setOnClickListener(v->pick()); root.addView(pick); preview=new ImageView(this); preview.setAdjustViewBounds(true); preview.setBackground(bg(Color.rgb(235,225,210),16)); root.addView(preview,new LinearLayout.LayoutParams(-1,dp(320))); EditText w=input("العرض mm — مثال 150"), h=input("الارتفاع mm — مثال 200"); root.addView(w); root.addView(h); Spinner style=spinner(new String[]{"قص الشخص فقط","لوحة كاملة","Floating","Halo","Reveal"}); Spinner display=spinner(new String[]{"بدون عرض","قاعدة مكتب","ستاند ضهر","حائط"}); root.addView(style); root.addView(display); Button save=button("💾 احفظ الطلب",false); save.setOnClickListener(v->save("صورة",material+" | "+w.getText()+"×"+h.getText()+" | "+style.getSelectedItem()+" | "+display.getSelectedItem())); root.addView(save); }
    private void pick(){ Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.addCategory(Intent.CATEGORY_OPENABLE); i.setType("image/*"); startActivityForResult(i,77); }
    @Override protected void onActivityResult(int r,int c,Intent d){ super.onActivityResult(r,c,d); if(r==77&&c==RESULT_OK&&d!=null){ imageUri=d.getData(); render(); } }
    private void render(){ if(preview==null||imageUri==null)return; try{ Bitmap s=BitmapFactory.decodeStream(getContentResolver().openInputStream(imageUri)); if(s==null)return; float sc=Math.min(1f,1200f/Math.max(s.getWidth(),s.getHeight())); if(sc<1)s=Bitmap.createScaledBitmap(s,(int)(s.getWidth()*sc),(int)(s.getHeight()*sc),true); int W=s.getWidth(),H=s.getHeight(); Bitmap o=Bitmap.createBitmap(W,H,Bitmap.Config.ARGB_8888); int[] p=new int[W*H]; s.getPixels(p,0,W,0,0,W,H); for(int i=0;i<p.length;i++){ int y=(int)(.299*Color.red(p[i])+.587*Color.green(p[i])+.114*Color.blue(p[i])); y=Math.max(0,Math.min(255,(int)((y-128)*1.25+128))); if(material.equals("خشب أسود"))y=255-y; if(material.equals("أكريليك أسود"))y=y>145?255:0; if(material.equals("ستانلس"))y=y>170?245:(y<70?15:y); p[i]=Color.rgb(y,y,y); } o.setPixels(p,0,W,0,0,W,H); preview.setImageBitmap(o); }catch(Exception e){Toast.makeText(this,"تعذر قراءة الصورة",Toast.LENGTH_SHORT).show();} }

    private void frames(){ page("البرواز والعرض","دخل المقاس والسماكة وصدّر SVG للـLightBurn"); EditText w=input("عرض الصورة mm"), h=input("ارتفاع الصورة mm"), t=input("سماكة الخشب mm"); t.setText("3"); root.addView(w); root.addView(h); root.addView(t); Spinner type=spinner(new String[]{"Floating","Halo","Reveal"}); root.addView(type); card("خيارات العرض","قاعدة مكتب • Stand ضهر • حائط"); Button ex=button("📄 صدّر SVG",true); ex.setOnClickListener(v->{ try{ double W=Double.parseDouble(w.getText().toString()),H=Double.parseDouble(h.getText().toString()),T=Double.parseDouble(t.getText().toString()); export("LH_FRAME_"+type.getSelectedItem()+".svg",frameSvg(type.getSelectedItem().toString(),W,H,T)); }catch(Exception e){Toast.makeText(this,"أدخل المقاسات أرقام",Toast.LENGTH_SHORT).show();} }); root.addView(ex); }
    private String frameSvg(String type,double w,double h,double t){ double e=type.equals("Halo")?Math.max(10,Math.min(w,h)*.07):Math.max(6,Math.min(w,h)*.04), bw=w+2*e,bh=h+2*e, slot=t+.25, base=Math.max(80,Math.min(w+30,w*.78)), bx=bw+25; return "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\""+(bw+base+80)+"mm\" height=\""+Math.max(bh+35,180)+"mm\"><g id=\"CUT_RED\" fill=\"none\" stroke=\"#ff0000\" stroke-width=\"0.18\"><rect x=\"5\" y=\"5\" width=\""+bw+"\" height=\""+bh+"\" rx=\"3\"/>"+(type.equals("Halo")?"<rect x=\""+(5+e)+"\" y=\""+(5+e)+"\" width=\""+w+"\" height=\""+h+"\" rx=\"3\"/>":"")+"<rect x=\""+bx+"\" y=\"8\" width=\""+base+"\" height=\"30\" rx=\"2\"/><rect x=\""+(bx+base*.18)+"\" y=\""+(23-slot/2)+"\" width=\""+(base*.64)+"\" height=\""+slot+"\"/><path d=\"M "+bx+" 135 L "+(bx+40)+" 135 L "+(bx+20)+" 60 Z\"/><circle cx=\"17\" cy=\"15\" r=\"2\"/><circle cx=\""+(bw-7)+"\" cy=\"15\" r=\"2\"/></g></svg>"; }

    private void packaging(){ page("التغليف","اختار النموذج وسجل القياس"); card("Portrait Sleeve","اقتصادي وخفيف للصور واللوحات"); card("Slide + Reveal","درج خشبي مناسب للهدايا"); card("Premium Reveal Box","فتح أرقى ورسالة داخلية"); EditText w=input("العرض mm"),h=input("الارتفاع mm"),d=input("العمق mm"); root.addView(w);root.addView(h);root.addView(d); Spinner s=spinner(new String[]{"Portrait Sleeve","Slide + Reveal","Puzzle Reveal","Magnetic Layers","Mini Book","Frame Box","Card → Stand","Hidden Message"}); root.addView(s); Button b=button("💾 احفظ اختيار التغليف",false); b.setOnClickListener(v->save("تغليف",s.getSelectedItem()+" | "+w.getText()+"×"+h.getText()+"×"+d.getText())); root.addView(b); }
    private void gifts(){ page("بوكسات الهدايا","شوف المحتويات الجاهزة قبل ما تقرر"); String[][] a={{"Memory Box","Portrait + ميدالية + رسالة + تاريخ"},{"Mother Box","Portrait + قلب + Stand Mama"},{"Father Box","Stand مكتب + ميدالية + Portrait صغير"},{"Teacher Box","حامل قلم + لوحة شكر + ميدالية اسم"},{"Jewelry Box","سلسلة/إسوارة + كارت اسم + رسالة"},{"Couple Box","Portrait + اسمين + تاريخ + Keychains"},{"Mini Memories","Mini Book + صور صغيرة + QR"}}; for(String[] x:a)card(x[0],x[1]); }
    private void occasions(){ page("المناسبات","أفكار ثابتة حتى ما تنسى شو فينا نعمل"); String[][] a={{"عيد الأم","Portrait أم • Stand Mama • Heart Family • Mother Box"},{"عيد الأب","Desk Stand • Portrait Family • Keychain • Father Box"},{"عيد المعلم","Teacher Stand • Pen Holder • Thank You Plaque • Teacher Box"},{"رمضان / العيد","فانوس اسم • هلال • دعاء • عيدية"},{"تخرج","لوحة اسم • سنة التخرج • ميدالية • Gift Box"},{"زواج / Valentine","Couple Portrait • اسمين • تاريخ • Love Box"},{"مولود","Name Plaque • Birth Details • Room Hanging"}}; for(String[] x:a)card(x[0],x[1]); }
    private void cards(){ page("كارت المشروع","5 اتجاهات أساسية Front / Back"); for(String s:new String[]{"Classic Center","Right Focus","Left Focus","Cutout Premium","Laser Signature"})card(s,"Front: Logo + لمسة حب • Back: QR + Instagram + TikTok + WhatsApp"); }

    private void save(String type,String d){ int n=prefs.getInt("n",0)+1; String id=String.format(Locale.US,"LH-%04d",n); prefs.edit().putInt("n",n).putString("j"+n,id+" | "+type+" | "+d+" | جديد").apply(); Toast.makeText(this,"تم حفظ "+id,Toast.LENGTH_LONG).show(); }
    private void orders(){ page("الطلبات","الطلبات المحفوظة على الهاتف"); int n=prefs.getInt("n",0); if(n==0){card("ما في طلبات بعد","أول طلب رح يظهر هون");return;} for(int i=n;i>0;i--)card("طلب",prefs.getString("j"+i,"")); }
    private void files(){ page("الملفات النهائية","ملفات SVG المصدرة من التطبيق"); File d=getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS); card("المسار",d==null?"غير متوفر":d.getAbsolutePath()); if(d!=null&&d.exists()){ File[] f=d.listFiles(); if(f!=null)for(File x:f)card(x.getName(),(x.length()/1024)+" KB"); } }
    private void export(String name,String content){ try{ File d=getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS); if(d==null)throw new Exception(); d.mkdirs(); File f=new File(d,name.replace(" ","_")); FileOutputStream o=new FileOutputStream(f); o.write(content.getBytes("UTF-8")); o.close(); Toast.makeText(this,"تم إنشاء "+f.getName(),Toast.LENGTH_LONG).show(); }catch(Exception e){Toast.makeText(this,"تعذر التصدير",Toast.LENGTH_SHORT).show();} }
}
